  r._start=r.started_at?stamp(r.started_at,"actual start"):null;r._end=r.finished_at?stamp(r.finished_at,"actual finish"):null;
  need(r._end===null||r._start!==null,"Actual finish needs actual start");need(r._start===null||r._time>=r._start,"Observation precedes actual start");need(r._end===null||(r._end>r._start&&r._time>=r._end),"Invalid actual completion interval");
